#include <bits/stdc++.h>
using namespace std;

const int MAXN = 50005;
const int MAXV = 1024; // 2^10

int N, M;
int A[MAXN];
int par[MAXN], dep[MAXN], heavy[MAXN], headN[MAXN], sz[MAXN];
vector<int> adj[MAXN];

// 树链剖分第一遍DFS
void dfs1(int u, int p) {
    par[u] = p;
    sz[u] = 1;
    heavy[u] = 0;
    dep[u] = p ? dep[p] + 1 : 0;
    int mx = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > mx) {
            mx = sz[v];
            heavy[u] = v;
        }
    }
}

// 树链剖分第二遍DFS
void dfs2(int u, int h) {
    headN[u] = h;
    if (heavy[u]) dfs2(heavy[u], h);
    for (int v : adj[u]) {
        if (v == par[u] || v == heavy[u]) continue;
        dfs2(v, v);
    }
}

// 提取u到v的路径节点序列
vector<int> extractPath(int u, int v) {
    vector<int> l, r;
    while (headN[u] != headN[v]) {
        if (dep[headN[u]] > dep[headN[v]]) {
            int h = headN[u];
            for (int x = u; ; x = par[x]) {
                l.push_back(x);
                if (x == h) break;
            }
            u = par[h];
        } else {
            int h = headN[v];
            for (int x = v; ; x = par[x]) {
                r.push_back(x);
                if (x == h) break;
            }
            v = par[h];
        }
    }
    if (dep[u] <= dep[v]) {
        for (int x = v; ; x = par[x]) {
            r.push_back(x);
            if (x == u) break;
        }
    } else {
        for (int x = u; ; x = par[x]) {
            l.push_back(x);
            if (x == v) break;
        }
    }
    reverse(r.begin(), r.end());
    l.insert(l.end(), r.begin(), r.end());
    return l;
}

int best_prev[6][MAXV], best_curr[6][MAXV];

int solve(vector<int>& path, int k) {
    int L = path.size();
    vector<int> S(L + 1);
    S[0] = 0;
    for (int i = 0; i < L; i++) {
        S[i + 1] = S[i] ^ A[path[i]];
    }
    
    int dp0[6], dp1[6];
    int next_dp0[6], next_dp1[6];
    
    for (int j = 0; j <= k; j++) {
        dp0[j] = -1;
        dp1[j] = -1;
        for (int v = 0; v < MAXV; v++) {
            best_prev[j][v] = -1;
            best_curr[j][v] = -1;
        }
    }
    
    dp0[0] = 0;
    best_prev[0][0] = 0; // 初始允许从0开始扩展
    
    for (int i = 1; i <= L; i++) {
        int si = S[i];
        int sprev = S[i - 1];
        
        // 利用前一状态留空的 dp0 值更新 best_curr，并滞后作为 best_prev 供扩展使用
        for (int j = 0; j <= k; j++) {
            if (dp0[j] > best_curr[j][sprev]) {
                best_curr[j][sprev] = dp0[j];
            }
            for (int v = 0; v < MAXV; v++) {
                best_prev[j][v] = best_curr[j][v];
            }
        }
        
        // 计算当前作为区段结尾的 dp1
        for (int j = 0; j <= k; j++) {
            next_dp1[j] = -1;
            if (j > 0) {
                for (int v = 0; v < MAXV; v++) {
                    if (best_prev[j - 1][v] >= 0) {
                        int val = best_prev[j - 1][v] + (v ^ si);
                        if (val > next_dp1[j]) {
                            next_dp1[j] = val;
                        }
                    }
                }
            }
        }
        
        // 计算当前留空的 dp0
        for (int j = 0; j <= k; j++) {
            next_dp0[j] = max(dp0[j], dp1[j]);
        }
        
        // 交换数组
        for (int j = 0; j <= k; j++) {
            dp0[j] = next_dp0[j];
            dp1[j] = next_dp1[j];
        }
    }
    
    return max(dp0[k], dp1[k]);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    cin >> N >> M;
    for (int i = 1; i <= N; i++) {
        cin >> A[i];
    }
    
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    
    dfs1(1, 0);
    dfs2(1, 1);
    
    for (int q = 0; q < M; q++) {
        int type;
        cin >> type;
        if (type == 1) {
            int u, x;
            cin >> u >> x;
            A[u] = x;
        } else {
            int u, v, k;
            cin >> u >> v >> k;
            vector<int> path = extractPath(u, v);
            cout << solve(path, k) << "\n";
        }
    }
    
    return 0;
}
